const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// WKWebView on iPad can insert a tab instead of moving to the next control.
function atlasMoveFocus(backward=false){
 const scope=document.querySelector('dialog[open]')||document;
 const controls=[...scope.querySelectorAll('input,select,textarea,button,a[href],[tabindex]')].filter(el=>el.tabIndex>=0&&!el.matches(':disabled,[readonly],input[type="hidden"]')&&!el.closest('[hidden],[inert]')&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
 if(!controls.length)return false;
 const current=controls.indexOf(document.activeElement),step=backward?-1:1;
 let next=current<0?(backward?controls.length-1:0):current+step;
 if(next<0||next>=controls.length){if(scope===document)return false;next=(next+controls.length)%controls.length;}
 controls[next].focus();return true;
}
document.addEventListener('keydown',event=>{
 if(event.key!=='Tab'||event.altKey||event.ctrlKey||event.metaKey||event.isComposing||event.defaultPrevented)return;
 if(atlasMoveFocus(event.shiftKey))event.preventDefault();
});
