const modelCatalogs={};
const profileDefaults={temperature:0.1,top_p:1,max_tokens:3072,context_length:0,reasoning_effort:''};
const catalogKey=name=>name+':'+providers[name]?.url;
function modelOptions(name,current){const items=modelCatalogs[catalogKey(name)]||[];return '<option value="">'+E(t('chooseAvailable'))+'</option>'+(!items.some(m=>m.id===current)&&current?`<option value="${E(current)}" selected>${E(current)} · ${t(modelCatalogs[catalogKey(name)]?'modelUnavailable':'catalogPending')}</option>`:'')+items.filter(m=>!['embedding','embeddings'].includes(m.type)).map(m=>m.managed_id?{...m,loaded:!!(managedState?.running&&managedState.active.name===name&&managedState.active.model===m.managed_id)}:m).map(m=>`<option value="${E(m.id)}" ${m.id===current?'selected':''}>${E(m.name)}${m.loaded===true?' · '+t('loadedModel'):m.loaded===false?' · '+t('unloadedModel'):''}</option>`).join('')}
function selectedMetadata(name,id){return (modelCatalogs[catalogKey(name)]||[]).find(m=>m.id===id)}
function reasoningOptions(name,id,value){const m=selectedMetadata(name,id);return `<option value="">${t('automatic')}${m?.default_reasoning?' ('+E(m.default_reasoning)+')':''}</option>`+(value&&!(m?.reasoning_levels||[]).includes(value)?`<option selected value="${E(value)}">${E(value)} · ${t('refreshModels')}</option>`:'')+(m?.reasoning_levels||[]).map(v=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(v)}</option>`).join('')}
function modelDescription(name,id){const m=selectedMetadata(name,id);if(!m)return t('unknownValue');return `${t('activeContext')}: ${E(m.active_context??t('unknownValue'))} · ${t('maximumContext')}: ${E(m.max_context??t('unknownValue'))}${m.quantization?' · '+E(m.quantization.name||m.quantization):''}`}
async function fetchCatalog(name,consent=false){const managed=await managedCatalog(name);if(managed)return managed;const r=await api('/providers/test',{method:'POST',body:{name,consent}});modelCatalogs[catalogKey(name)]=r.catalog;return r}
const t=k=>words[lang][k]||words.es[k]||k;
const icons={collections:'<path d="M3 6h6l2 2h10v12H3z"/><path d="M3 6V4h7l2 2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',analysis:'<path d="M3 3v18h18M7 16v-5m5 5V7m5 9V4"/>',providers:'<path d="m12 2 9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 6"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>'};
const icon=k=>'<svg viewBox="0 0 24 24">'+icons[k]+'</svg>';
const bytes=n=>n>=1073741824?(n/1073741824).toFixed(1)+' GB':n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':(n||0)+' B';
const date=n=>n?new Date(n*1000).toLocaleString(lang==='es'?'es-ES':'en-GB'):'—';
let toastTimer;
function toast(s,error=false){$('#toast').textContent=s;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,error?12000:4000)}
async function api(path,{method='GET',body,headers={}}={}){const options={method,headers:{'X-RAG':'1',...headers},credentials:'same-origin'};if(body!==undefined){if(body instanceof FormData)options.body=body;else{options.body=JSON.stringify(body);options.headers['Content-Type']='application/json'}}let res=await fetch('/api'+path,options);if(!res.ok){let e=await res.json().catch(()=>({detail:res.statusText}));if(res.status===401&&me){me=null;await authenticate(false)}throw Error(typeof e.detail==='string'?e.detail:JSON.stringify(e.detail))}return res.json()}
async function busy(button,fn){const changesText=button?.tagName==='BUTTON';let old=button?.textContent;if(button){button.disabled=true;if(changesText)button.textContent=t('loading')}try{return await fn()}catch(e){toast(e.message,true)}finally{if(button){button.disabled=false;if(changesText)button.textContent=old}}}
function bind(selector,event,fn){const el=$(selector);if(el)el.addEventListener(event,fn)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
bind('#close-modal','click',close);
function translateShell(){$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('#language').value=lang;document.documentElement.lang=lang;$('#identity').textContent=me?me.username+' · '+t(me.role):'';$('#nav').innerHTML=Object.keys(icons).filter(k=>k!=='users'||me.role==='admin').map(k=>`<button data-page="${k}" aria-label="${E(t(k))}" title="${E(t(k))}" class="${k===page?'active':''}">${icon(k)}<span>${t(k)}</span></button>`).join('');$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page))}
bind('#language','change',async e=>{lang=e.target.value;localStorage.setItem('atlas-language',lang);translateShell();await navigate(page)});
bind('#logout','click',async()=>{await api('/logout',{method:'POST'});for(const k of Object.keys(modelCatalogs))delete modelCatalogs[k];me=null;await authenticate(false)});
async function authenticate(setup){$('#shell').hidden=true;$('#auth').hidden=false;$('#auth').innerHTML=`<div class="auth-card"><div class="brand"><span class="brand-icon">a</span><div>atlas<span>RAG LOCAL</span></div></div><h1>${t(setup?'setup':'signIn')}</h1><p>${t(setup?'setupDesc':'loginDesc')}</p><form id="auth-form"><label>${t('username')}<input id="auth-user" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" required minlength="2"></label><label>${t('password')}<input id="auth-password" type="password" autocomplete="${setup?'new-password':'current-password'}" required minlength="10" placeholder="${t('minPassword')}"></label><div class="error-text" id="auth-error"></div><button class="primary">${t(setup?'create':'login')}</button></form><p>LOCAL · PRIVATE · YOURS</p></div>`;bind('#auth-form','submit',e=>{e.preventDefault();busy($('#auth-form button'),async()=>{try{me=await api(setup?'/setup':'/login',{method:'POST',body:{username:$('#auth-user').value,password:$('#auth-password').value},headers:setup?{'X-Setup-Token':setupToken}:{}});sessionStorage.removeItem('atlas-setup');setupToken='';$('#auth').hidden=true;$('#shell').hidden=false;translateShell();await navigate('collections')}catch(err){$('#auth-error').textContent=err.message;throw err}})});}
async function refreshData(){[cols,stats,providers]=await Promise.all([api('/collections'),api('/stats'),api('/providers')]);$('#footer-status').textContent=bytes(stats.rss)+' RAM · '+bytes(stats.disk.free)+' '+t('freeDisk')+' · '+(stats.disk.volume||'');}
function title(eye,heading,sub,actions=''){$('#eyebrow').textContent=eye;$('#page-title').textContent=heading;$('#page-subtitle').textContent=sub;$('#page-actions').innerHTML=actions;$('#crumb').textContent=t(page)}
async function navigate(next){page=next;activeCollection=null;translateShell();try{await refreshData();await ({collections:renderCollections,search:renderSearch,analysis:renderAnalysis,providers:renderProviders,users:renderUsers,activity:renderActivity}[page])()}catch(e){toast(e.message,true)}}
function metric(label,value,hint){return `<div class="metric"><div class="label">${label}</div><div class="number">${E(value)}</div><div class="hint">${hint}</div></div>`}
function metrics(){return '<div class="metrics">'+metric(t('files'),stats.files,t('supported'))+metric(t('fragments'),stats.chunks,t('localIndex'))+metric(t('memory'),bytes(stats.rss),t('ownProcesses'))+metric(t('freeDisk'),bytes(stats.disk.free),E(stats.disk.volume||t('localServer'))+(stats.disk.path?'<br>'+E(stats.disk.path):''))+'</div>'}
function canEdit(c){return me.role==='admin'||(me.role==='editor'&&c.permission==='edit')}
async function renderCollections(){title(t('eyebrow'),t('colTitle'),t('colSub'),me.role==='admin'?`<button class="primary" id="add-collection">＋ ${t('newCollection')}</button>`:'');$('#content').innerHTML=metrics()+`<div class="section-bar"><h2>${t('collectionsTitle')} <span class="muted">/ ${cols.length}</span></h2><span class="muted">${t('localFirst')}</span></div>`+(cols.length?`<div class="cards">${cols.map(c=>`<article class="card"><div class="collection-top"><div class="folder-icon">▱</div><span class="badge ${c.indexed?'good':''}">${t(c.status==='indexing'?'indexing':c.indexed?'indexed':'notIndexed')}</span></div><h2>${E(c.name)}</h2><div class="path">${E(c.path||t('permission')+' · '+t(c.permission==='edit'?'write':'read'))}</div><div class="card-meta"><span>${c.files} ${t('files').toLowerCase()}</span><span>${c.chunks} ${t('fragments').toLowerCase()}</span><span>${bytes(c.bytes)}</span></div><div class="card-actions"><button class="small" data-open="${c.id}">${t('open')} ↗</button>${canEdit(c)?`<button class="small" data-index="${c.id}">${t('index')}</button>`:''}${me.role==='admin'?`<button class="text-button small" data-config="${c.id}">${t('settings')}</button>`:''}</div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-mark">▱</div><h2>${t('emptyTitle')}</h2><p>${t('emptyText')}</p>${me.role==='admin'?`<button class="primary" id="empty-add">＋ ${t('newCollection')}</button>`:''}</div>`)+`<div class="notice">${t('supported')}<br>${t('localFirst')}</div>`;bind('#add-collection','click',()=>collectionForm());bind('#empty-add','click',()=>collectionForm());$$('[data-open]').forEach(b=>b.onclick=()=>openCollection(+b.dataset.open));$$('[data-index]').forEach(b=>b.onclick=()=>busy(b,()=>indexCollection(+b.dataset.index)));$$('[data-config]').forEach(b=>b.onclick=()=>collectionForm(cols.find(c=>c.id===+b.dataset.config)));}
async function indexCollection(id,force=false){await api(`/collections/${id}/index`,{method:'POST',body:{force}});toast(t('indexing'));await refreshData();if(activeCollection)await openCollection(id);else await renderCollections()}
let embeddingRequest=0,embeddingCatalog=[],embeddingManaged=false;
async function refreshEmbeddingModels(current='',startMotor=false){
 const request=++embeddingRequest, provider=$('#col-embedding')?.value, select=$('#col-model'), status=$('#col-model-status'), refresh=$('#col-model-refresh');
 if(!select)return;
 select.required=!['apple','none'].includes(provider);select.disabled=true;refresh.hidden=!select.required;status.textContent='';
 if(provider==='apple'||provider==='none'){
  if(startMotor&&(await managedInfo())?.config.enabled)await engineOperation('stop');
  select.innerHTML=`<option value="">${E(provider==='apple'?t('embeddingApple')+' · '+($('#col-language').value==='es'?'Español':'English'):t('embeddingNone'))}</option>`;return;
 }
 select.innerHTML=`<option value="">${E(t('loading'))}</option>`;refresh.disabled=true;
 try{
  if(startMotor){const manager=await managedInfo();if(manager?.config.enabled){status.textContent=et('Arrancando servidor en el Mac…','Starting server on the Mac…');await engineOperation(provider);}}
  const result=await api('/providers/'+provider+'/embedding-models');
  if(request!==embeddingRequest||!select.isConnected)return;
  embeddingCatalog=result.catalog;embeddingManaged=result.managed;
  select.innerHTML=`<option value="">${E(t('chooseAvailable'))}</option>`+result.catalog.map(m=>`<option value="${E(m.id)}" ${m.id===current?'selected':''}>${E(m.name)}${m.loaded===false?' · '+t('unloadedModel'):''}</option>`).join('');
  select.disabled=false;status.textContent='';
  if(!result.catalog.length)status.textContent=lang==='es'?'No hay modelos de embeddings disponibles en este servidor. Activa uno compatible y actualiza la lista.':'No embedding models are available on this server. Enable a compatible model and refresh.';
  else if(current&&!result.catalog.some(m=>m.id===current))status.textContent=t('modelUnavailable');
 }catch(e){
  if(request!==embeddingRequest||!select.isConnected)return;
  select.innerHTML=`<option value="">${E(t('chooseAvailable'))}</option>`;select.disabled=false;status.textContent=e.message;
 }finally{if(request===embeddingRequest&&refresh.isConnected)refresh.disabled=false;}
}
async function loadEmbeddingSelection(){
 const select=$('#col-model'),provider=$('#col-embedding').value,status=$('#col-model-status'),save=$('#collection-form button.primary'),engine=$('#col-embedding'),refresh=$('#col-model-refresh');
 const entry=embeddingCatalog.find(m=>m.id===select.value);if(!entry)return;
 if(!embeddingManaged){status.textContent=et('Servidor externo: comprueba que el modelo está cargado.','External server: make sure the model is loaded.');return;}
 select.disabled=true;save.disabled=true;engine.disabled=true;refresh.disabled=true;
 status.textContent=et('Cargando modelo de embeddings en el Mac…','Loading embedding model on the Mac…');
 try{await engineOperation(provider,entry.managed_id,4096);if(status.isConnected)status.textContent=et('Modelo cargado y servidor listo en el Mac.','Model loaded and server ready on the Mac.');}
 catch(e){if(select.isConnected){select.value='';status.textContent=e.message;}}
 finally{if(select.isConnected){select.disabled=false;save.disabled=false;engine.disabled=false;refresh.disabled=false;}}
}
function collectionForm(c){modal(`<h2>${t(c?'collectionConfig':'newCollection')}</h2><form class="stack" id="collection-form"><label>${t('name')}<input id="col-name" required value="${E(c?.name||'')}" placeholder="${t('collectionName')}"></label><label>${t('path')}<div class="row"><input class="grow" id="col-path" required value="${E(c?.path||'')}" placeholder="${t('folderPlaceholder')}" readonly>${!c?`<button type="button" id="choose-folder">${t('choose')}</button>`:''}</div></label><div class="grid2"><label>${t('language')}<select id="col-language"><option value="es">Español</option><option value="en">English</option></select></label><label>${t('embeddingEngine')}<select id="col-embedding"><option value="apple">${t('apple')}</option><option value="none">${t('textOnly')}</option>${['llama','omlx','vllm','lmstudio'].map(x=>`<option value="${x}">${providerName(x)}</option>`).join('')}</select></label></div><p class="muted" id="col-embedding-help">${t('embeddingHelp')}</p><label>${t('embeddingModel')}<select aria-describedby="col-embedding-help col-model-status" id="col-model"></select></label><div class="row"><button type="button" id="col-model-refresh">${t('refreshModels')}</button><span class="muted" id="col-model-status" aria-live="polite"></span></div><label>${t('exclusions')}<textarea id="col-exclusions" placeholder="*.tmp&#10;archive/*">${E((c?.exclusions||[]).join('\n'))}</textarea></label><label class="inline"><input type="checkbox" id="col-autoscan" ${c?.autoscan?'checked':''}>${t('autoscan')}</label><div class="row"><button class="primary">${t('save')}</button>${c?`<button type="button" id="remove-collection" class="danger">${t('delete')}</button>`:''}</div></form>`);$('#col-language').value=c?.language||'es';$('#col-embedding').value=c?.embedding||'apple';bind('#col-embedding','change',()=>refreshEmbeddingModels('',true));bind('#col-model','change',loadEmbeddingSelection);bind('#col-language','change',()=>refreshEmbeddingModels());bind('#col-model-refresh','click',()=>refreshEmbeddingModels($('#col-model').value));refreshEmbeddingModels(c?.model||'');bind('#choose-folder','click',()=>{if(window.webkit?.messageHandlers?.chooseFolder)window.webkit.messageHandlers.chooseFolder.postMessage({});else openFolderBrowser()});bind('#collection-form','submit',e=>{e.preventDefault();busy($('#collection-form button.primary'),async()=>{await api('/collections'+(c?'/'+c.id:''),{method:c?'PATCH':'POST',body:{name:$('#col-name').value,path:$('#col-path').value,language:$('#col-language').value,embedding:$('#col-embedding').value,model:$('#col-model').value,exclusions:$('#col-exclusions').value.split('\n').map(x=>x.trim()).filter(Boolean),autoscan:$('#col-autoscan').checked}});close();toast(t('saved'));await navigate('collections')})});bind('#remove-collection','click',()=>{if(confirm(t('deleteConfirm')))busy($('#remove-collection'),async()=>{await api('/collections/'+c.id,{method:'DELETE'});close();await navigate('collections')})})}
function applyCollectionFolder(path){const input=$('#col-path'),name=$('#col-name');if(!input||!name)return;input.value=path;const suggested=path.replace(/\/+$/,'').split('/').pop()||path;if(!name.value.trim()||name.value===name.dataset.folderName)name.value=suggested;name.dataset.folderName=suggested}
window.atlasFolderChosen=applyCollectionFolder;
async function openFolderBrowser(){
 const form=$('#collection-form'),heading=$('#modal-content > h2');if(!form)return;
 form.hidden=true;if(heading)heading.hidden=true;
 const holder=document.createElement('section');holder.id='folder-browser';holder.className='stack';$('#modal-content').append(holder);
 let current='',sequence=0,filterTimer;
 const finish=()=>{clearTimeout(filterTimer);holder.remove();form.hidden=false;if(heading)heading.hidden=false};
 async function load(path='',q=''){
  const request=++sequence;holder.innerHTML=`<h2>${t('folderBrowser')}</h2><p class="muted">${t('loading')}</p>`;
  try{const r=await api('/folders?'+new URLSearchParams({path,q}));if(request!==sequence||!holder.isConnected)return;current=r.path;
   holder.innerHTML=`<h2>${t('folderBrowser')}</h2><p class="muted">${t('folderBrowserHelp')}</p><div class="row"><button type="button" id="folder-roots">⌂ ${t('folderRoots')}</button>${r.path?`<button type="button" id="folder-up">↑ ${t('folderUp')}</button>`:''}</div><code class="folder-current">${E(r.path||t('folderRoots'))}</code><label>${t('folderFilter')}<input id="folder-filter" type="search" value="${E(q)}" autocapitalize="none" autocomplete="off"></label><div class="folder-list">${r.directories.map(d=>`<button type="button" class="folder-row" data-folder-path="${E(d.path)}"><span>▱ ${E(d.name)}</span><span aria-hidden="true">›</span></button>`).join('')||`<p class="muted">${t('folderEmpty')}</p>`}</div>${r.truncated?`<p class="muted">${t('folderMore')}</p>`:''}<div class="row"><button type="button" class="primary" id="folder-use" ${r.selectable?'':'disabled'}>${t('folderUse')}</button><button type="button" id="folder-cancel">${t('cancel')}</button></div>`;
   holder.querySelectorAll('[data-folder-path]').forEach(b=>b.onclick=()=>load(b.dataset.folderPath));
   holder.querySelector('#folder-roots').onclick=()=>load('');const up=holder.querySelector('#folder-up');if(up)up.onclick=()=>load(r.parent||'');
   holder.querySelector('#folder-use').onclick=()=>{applyCollectionFolder(current);finish()};holder.querySelector('#folder-cancel').onclick=finish;
   const input=holder.querySelector('#folder-filter');input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();load(current,input.value)}};
  }catch(e){if(holder.isConnected){holder.innerHTML=`<h2>${t('folderBrowser')}</h2><p class="error-text">${E(e.message)}</p><div class="row"><button type="button" id="folder-retry">${t('folderRoots')}</button><button type="button" id="folder-cancel">${t('cancel')}</button></div>`;holder.querySelector('#folder-retry').onclick=()=>load('');holder.querySelector('#folder-cancel').onclick=finish}}
 }
 await load($('#col-path').value||'');
}

async function openCollection(id){const c=cols.find(c=>c.id===id);if(!c)return;activeCollection=id;const files=await api(`/collections/${id}/files`);title(t('collections'),c.name,c.path||'',`<button id="back">← ${t('back')}</button>`);$('#content').innerHTML=`<div class="row"><span class="badge">${c.files} ${t('files')} · ${c.chunks} ${t('fragments')}</span><span class="grow"></span>${canEdit(c)?`<input type="file" id="upload-file" aria-label="${t('upload')}"><button id="upload">${t('upload')}</button><button id="index-now" class="primary">${t('index')}</button><button id="reindex">${t('reindex')}</button>`:''}</div><div class="spacer"></div>`+(files.length?`<div class="data-table-wrap"><table><thead><tr><th>${t('file')}</th><th>${t('status')}</th><th>${t('size')}</th><th>${t('updated')}</th><th></th></tr></thead><tbody>${files.map(f=>`<tr><td class="file-path">${E(f.path)}${f.duplicate_of?` <span class="badge">${t('duplicate')}</span>`:''}${f.error?`<span class="sub error-text">${E(f.error)}</span>`:''}</td><td><span class="badge ${f.status==='indexed'?'good':''}">${f.status==='indexed'?t('indexed'):E(f.status)}</span></td><td>${bytes(f.size)}</td><td>${date(f.mtime)}</td><td><button class="small" data-preview="${f.id}">${t('preview')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><p>${t('noFiles')}</p></div>`);bind('#back','click',()=>navigate('collections'));bind('#index-now','click',e=>busy(e.target,()=>indexCollection(id)));bind('#reindex','click',e=>busy(e.target,()=>indexCollection(id,true)));bind('#upload','click',e=>busy(e.target,async()=>{const f=$('#upload-file').files[0];if(!f)return;const form=new FormData();form.append('file',f);await api(`/collections/${id}/upload`,{method:'POST',body:form});toast(t('indexing'));}));$$('[data-preview]').forEach(b=>b.onclick=()=>preview(+b.dataset.preview));}
async function preview(id){try{const p=await api(`/files/${id}/preview`);const c=cols.find(c=>c.id===p.file.collection_id);modal(`<h2>${E(p.file.path)}</h2><p class="muted">${t('editNotice')}</p><div class="row"><a href="/api/files/${id}/download" download>${t('download')} ↗</a>${p.file.path.toLowerCase().endsWith('.pdf')?`<a href="/api/files/${id}/pdf" target="_blank">${t('openOriginal')} ↗</a>`:''}${p.editable&&canEdit(c)?`<button class="small" id="edit-file">${t('edit')}</button>`:''}${canEdit(c)?`<button class="small danger" id="trash-file">${t('trash')}</button>`:''}</div><div id="preview-body">${p.sections.map(s=>`<p class="muted">${E(s.locator)}</p><pre>${E(s.text)}</pre>`).join('')}</div>`);bind('#edit-file','click',e=>busy(e.target,async()=>{let d=await api(`/files/${id}/text`);$('#preview-body').innerHTML=`<textarea id="file-text" class="code-editor">${E(d.text)}</textarea><div class="spacer"></div><button class="primary" id="save-file">${t('save')}</button>`;bind('#save-file','click',ev=>busy(ev.target,async()=>{await api(`/files/${id}/text`,{method:'PUT',body:{text:$('#file-text').value,sha:d.sha}});close();toast(t('saved'));if(activeCollection)await openCollection(activeCollection)}))}));bind('#trash-file','click',e=>{if(confirm(t('trashConfirm')))busy(e.target,async()=>{await api(`/files/${id}/trash`,{method:'POST',body:{confirm:true}});close();await refreshData();if(activeCollection)await openCollection(activeCollection)})})}catch(e){toast(e.message,true)}}
let managedState=null,managedModels={};
async function managedInfo(){if(me?.role!=='admin')return null;managedState=await api('/engines');return managedState}
async function managedCatalog(name){const status=await managedInfo();if(!status?.config.enabled||name==='openai')return null;const items=await api(`/engines/${name}/models`);managedModels[name]=items;const catalog=items.map(m=>({...m,id:m.api_model,managed_id:m.id}));modelCatalogs[catalogKey(name)]=catalog;return {catalog,models:catalog.map(m=>m.id)}}
function showEngineOperation(message,error=false){
 let banner=$('#engine-operation');if(!banner){banner=document.createElement('div');banner.id='engine-operation';banner.className='notice';banner.setAttribute('role','status');$('#content').before(banner);}
 banner.textContent=message;banner.classList.toggle('error-text',error);
 if($('#engine-status'))$('#engine-status').textContent=message;
}
let engineQueue=Promise.resolve();
function engineOperation(name,model='',context=4096){
 const operation=engineQueue.then(()=>performEngineOperation(name,model,context));
 engineQueue=operation.catch(()=>{});return operation;
}
async function performEngineOperation(name,model='',context=4096){
 showEngineOperation(et('Solicitud enviada al Mac. Arrancando o cambiando el motor…','Request sent to the Mac. Starting or switching engine…'));
 try{
  const deadline=Date.now()+240000;while((await managedInfo()).job.busy){if(Date.now()>deadline)throw Error(et('El Mac sigue ocupado; vuelve a intentarlo.','The Mac is still busy; retry.'));await new Promise(r=>setTimeout(r,500));}
  await api('/engines/action',{method:'POST',body:{action:name==='stop'?'stop':'select',name:name==='stop'?'llama':name,model,context}});
  let completed;
  for(;;){if(Date.now()>deadline)throw Error(et('Tiempo de espera agotado; revisa el estado del Mac.','Timed out; check the Mac state.'));const s=await managedInfo();showEngineOperation(s.job.busy?et('El Mac está cargando el servidor o modelo. Espera…','The Mac is loading the server or model. Please wait…'):engineSummary(s),!!s.job.error);const lm=$('#lmstudio-state');if(lm)lm.textContent=lmstudioSummary(s);if(!s.job.busy){if(s.job.error)throw Error(s.job.error);completed=s;break}await new Promise(r=>setTimeout(r,750))}
  await refreshData();$$('[data-provider-form]').forEach(f=>{const n=f.dataset.providerForm,current=f.elements.model.value;f.elements.url.value=providers[n].url;f.elements.model.innerHTML=modelOptions(n,current);f.elements.model.value=current});
  if(model&&(!completed.running||completed.active.model!==model))throw Error(et('El Mac no confirmó la carga del modelo seleccionado.','The Mac did not confirm loading the selected model.'));
  showEngineOperation(name==='stop'?et('Motores de Atlas parados.','Atlas engines stopped.'):completed.running?et('Listo en el Mac: ','Ready on the Mac: ')+engineSummary(completed):et('Elige un modelo para arrancar este motor.','Choose a model to start this engine.'));
 }catch(e){showEngineOperation(e.message,true);throw e;}
}

function et(es,en){return lang==='en'?en:es}
function engineSummary(s){const a=s.active;return (s.running?`${providerName(a.name)} · ${a.api_model||et('sin modelo cargado','no model loaded')} · ${s.rss==null?et('RAM compartida de LM Studio','LM Studio shared RAM'):bytes(s.rss)+' RAM'}`:et('Todos los motores de Atlas están parados.','All Atlas engines are stopped.'))+(s.job.error?' · '+s.job.error:'')}
function lmstudioSummary(s){const l=s.lmstudio||{};return `LM Studio · ${et('Aplicación','Application')}: ${l.application_running?et('abierta','open'):et('cerrada','closed')} · API: ${l.api_running?et('activa','running'):et('parada','stopped')} · ${et('Modelos cargados','Loaded models')}: ${l.loaded_models??'—'}`}
async function managedSelection(name,apiModel='',context){if(!name)throw Error(et('Selecciona un servidor.','Select a server.'));const s=await managedInfo();if(!s?.config.enabled)return false;if(name==='openai'){await engineOperation('stop');return true}const items=await api(`/engines/${name}/models`);managedModels[name]=items;const item=items.find(m=>m.api_model===apiModel);if(apiModel&&!item)throw Error(et('El modelo ya no figura en el catálogo del Mac. Actualiza la lista.','The model is no longer in the Mac catalog. Refresh the list.'));await engineOperation(name,item?.id||'',context||4096);return true}
async function renderEngineManager(){
 if(me.role!=='admin')return;const holder=$('#engine-manager');if(!holder)return;const s=await managedInfo();
 holder.innerHTML=`<div class="panel stack"><h2>${et('Motores locales · control de memoria','Local engines · memory control')}</h2><p class="muted">${et('La gestión automática arranca un motor dedicado de Atlas. Cambiar de modelo descarga el anterior de la RAM; cambiar de motor cierra sus procesos antes de arrancar el siguiente. Los archivos de los modelos se conservan.','Automatic management starts a dedicated Atlas engine. Switching models unloads the previous weights; switching engines closes its processes before starting the next one. Model files are preserved.')}</p><label class="inline"><input type="checkbox" id="engine-enabled" ${s.config.enabled?'checked':''}>${et('Gestionar automáticamente los motores desde Atlas','Automatically manage engines from Atlas')}</label><div class="grid2"><label>${et('Servidor local','Local server')}<select id="engine-name"><option value="" disabled ${!s.running?'selected':''}>${et('Selecciona un servidor','Select a server')}</option>${['llama','omlx','vllm','lmstudio'].map(n=>`<option value="${n}" ${s.active.name===n?'selected':''}>${providerName(n)}${s.available[n]?'':' · '+et('no instalado','not installed')}</option>`).join('')}</select></label><label>${et('Modelo instalado en disco','Model installed on disk')}<select id="engine-model"><option value="">${et('Selecciona un modelo','Select a model')}</option></select></label></div><label>${et('Contexto al cargar el modelo (tokens)','Context when loading the model (tokens)')}<input type="number" id="engine-context" min="512" max="32768" step="512" value="${s.active.context||4096}"></label><div id="engine-model-size" class="muted"></div><div class="row"><button id="engine-load" type="button" class="primary">${et('Arrancar / cargar modelo','Start / load model')}</button><button id="engine-stop" type="button" class="danger">${et('Parar todos los motores de Atlas y liberar memoria','Stop all Atlas engines and release memory')}</button><button id="engine-log" type="button">${t('logs')}</button></div><button id="engine-stop-detected" type="button" class="danger">${et('Parar también todos los motores externos detectados…','Also stop all detected external engines…')}</button><p id="engine-status" class="muted" role="status">${E(engineSummary(s))}</p><p class="muted" id="lmstudio-state">${lmstudioSummary(s)}</p><details><summary>${et('Carpetas de modelos','Model directories')}</summary><div class="stack"><p class="muted">${et('Solo modelos ya instalados; no se descargan pesos de Internet. Atlas abre y cierra también la aplicación LM Studio. vLLM arranca cuando eliges un modelo.','Only models already installed; no weights are downloaded. Atlas also opens and quits the LM Studio application. vLLM starts once you choose a model.')}</p><textarea id="engine-roots">${E(s.config.roots.join('\n'))}</textarea><button type="button" id="engine-save-roots">${t('save')}</button></div></details></div>`;
 const name=$('#engine-name'),model=$('#engine-model'),context=$('#engine-context');
 const detail=()=>{const m=(managedModels[name.value]||[]).find(x=>x.id===model.value);$('#engine-model-size').textContent=m?`${m.name} · ${bytes(m.size_bytes)} ${et('pesos en disco; se comprueba la RAM antes de cargar','weights on disk; RAM is checked before loading')}`:''};
 const fill=async()=>{if(!name.value){model.innerHTML='<option value="">'+t('chooseAvailable')+'</option>';return}const items=await api(`/engines/${name.value}/models`);managedModels[name.value]=items;model.innerHTML=`<option value="">${et('Selecciona un modelo','Select a model')}</option>`+items.map(m=>`<option value="${m.id}">${E(m.name)} · ${bytes(m.size_bytes)}</option>`).join('');if(managedState?.active.name===name.value)model.value=managedState.active.model||'';detail()};
 const load=async()=>{if(!$('#engine-enabled').checked)throw Error(et('Activa la gestión automática primero.','Enable automatic management first.'));await engineOperation(name.value,model.value,+context.value);await fill()};
 name.onchange=e=>busy(e.target,async()=>{model.value='';await fill();if($('#engine-enabled').checked){await engineOperation(name.value,'',+context.value);await fill()}});
 model.onchange=e=>busy(e.target,async()=>{detail();if($('#engine-enabled').checked)await load()});
 $('#engine-enabled').onchange=e=>busy(e.target,async()=>{try{await api('/engines/config',{method:'POST',body:{enabled:e.target.checked}})}catch(err){e.target.checked=!e.target.checked;throw err}});
 $('#engine-load').onclick=e=>busy(e.target,load);$('#engine-stop').onclick=e=>busy(e.target,async()=>{await engineOperation('stop');name.value='';model.value='';detail()});
 $('#engine-log').onclick=e=>busy(e.target,async()=>{const r=await api(`/engines/${name.value}/log`);modal(`<h2>${t('logs')} · ${providerName(name.value)}</h2><pre>${E(r.text||'—')}</pre>`)});
 $('#engine-stop-detected').onclick=e=>busy(e.target,async()=>{const r=await api('/engines/detected');const list=r.servers.map(x=>`${providerName(x.name)} · ${x.pid?'PID '+x.pid:'API '+x.port}`).join('\n');if(!confirm(et('Se descargarán los modelos y se detendrán estos servidores, interrumpiendo sus consultas activas. Se cerrará también la aplicación LM Studio. Los archivos se conservan.\n\n','Models will be unloaded and these servers stopped, interrupting active requests. LM Studio will also quit. Files are preserved.\n\n')+(list||et('Ningún motor externo detectado.','No external engines detected.'))))return;await api('/engines/action',{method:'POST',body:{action:'stop-detected',confirmation:r.confirmation}});while((await managedInfo()).job.busy)await new Promise(r=>setTimeout(r,750));const s=await managedInfo();if(s.job.error)throw Error(s.job.error);$('#engine-status').textContent=engineSummary(s)});
 $('#engine-save-roots').onclick=e=>busy(e.target,async()=>{await api('/engines/config',{method:'POST',body:{enabled:$('#engine-enabled').checked,roots:$('#engine-roots').value.split('\n').map(x=>x.trim()).filter(Boolean)}});await fill();toast(t('saved'))});await fill();
}

function providerName(k){return {llama:'llama.cpp',omlx:'oMLX',vllm:'vLLM',lmstudio:'LM Studio',openai:'OpenAI'}[k]||k}
function providerControls(prefix){return `<div class="grid2 provider-fields"><label>${t('provider')}<select id="${prefix}-provider"><option value="" disabled>${et('Selecciona un servidor','Select a server')}</option>${Object.keys(providers).map(x=>`<option value="${x}">${providerName(x)}</option>`).join('')}</select></label><label>${t('model')}<select id="${prefix}-model"></select></label></div><label id="${prefix}-reasoning-label" hidden>${t('reasoning')}<select id="${prefix}-reasoning"></select></label><p class="muted" id="${prefix}-metadata"></p><label class="inline" id="${prefix}-consent-label" hidden><input type="checkbox" id="${prefix}-consent">${t('consent')}</label><button type="button" id="${prefix}-activate">${et('Arrancar / activar servidor','Start / activate server')}</button><button type="button" id="${prefix}-refresh">${t('refreshModels')}</button>`}
function bindProvider(prefix){
 const select=$(`#${prefix}-provider`),model=$(`#${prefix}-model`),reasoning=$(`#${prefix}-reasoning`),activate=$(`#${prefix}-activate`),refreshButton=$(`#${prefix}-refresh`);
 select.value='';
 const detail=()=>{const n=select.value;if(!n){model.innerHTML='<option value="">'+t('chooseAvailable')+'</option>';model.disabled=true;activate.disabled=true;$(`#${prefix}-metadata`).textContent=et('Selecciona un servidor para arrancarlo en el Mac.','Select a server to start it on the Mac.');return}const p={...profileDefaults,...providers[n]?.profiles?.[model.value]};$(`#${prefix}-reasoning-label`).hidden=n!=='openai';reasoning.innerHTML=reasoningOptions(n,model.value,p.reasoning_effort);$(`#${prefix}-metadata`).textContent=modelDescription(n,model.value).replace(/&[^;]+;/g,'')+(n!=='openai'?` · ${t('temperature')}: ${p.temperature} · ${t('maxTokens')}: ${p.max_tokens} · ${t('contextLimit')}: ${p.context_length||t('automatic')}`:'');activate.disabled=false;model.disabled=false};
 const fill=()=>{if(!select.value)return detail();const current=model.value||providers[select.value]?.model||'';model.innerHTML=modelOptions(select.value,current);model.value=current;detail()};
 const change=async(start=false)=>{const n=select.value;if(!n)return detail();model.disabled=true;model.innerHTML='';$(`#${prefix}-consent-label`).hidden=n!=='openai';if(start){$(`#${prefix}-consent`).checked=false;await managedSelection(n);localStorage.setItem('atlas-provider',n)}if(n!=='openai'||$(`#${prefix}-consent`).checked){await fetchCatalog(n,$(`#${prefix}-consent`).checked);if(select.isConnected&&select.value===n)fill()}else detail()};
 select.onchange=e=>busy(e.target,()=>change(true));
 model.onchange=e=>busy(e.target,async()=>{if(!model.value)return;await managedSelection(select.value,model.value);await fetchCatalog(select.value);fill()});
 activate.onclick=e=>busy(e.target,async()=>{if(!select.value)return;await managedSelection(select.value,model.value);await change()});
 refreshButton.onclick=e=>busy(e.target,()=>change(true));
 $(`#${prefix}-consent`).onchange=e=>{if(e.target.checked)busy(refreshButton,()=>change())};
 detail();managedInfo().then(status=>{if(!select.isConnected||select.value)return;if(status?.running&&providers[status.active.name]){select.value=status.active.name;return change()}if(me.role!=='admin'){select.value=localStorage.getItem('atlas-provider')||'lmstudio';return change()}}).catch(e=>{$(`#${prefix}-metadata`).textContent=e.message});
}
function providerValues(prefix){return {provider:$(`#${prefix}-provider`).value,model:$(`#${prefix}-model`).value,reasoning_effort:$(`#${prefix}-reasoning`).value,consent:$(`#${prefix}-consent`).checked}}
async function renderSearch(){title('RETRIEVAL + GENERATION',t('searchTitle'),t('searchSub'));$('#content').innerHTML=`<div class="split"><div class="panel stack"><h2>${t('scope')}</h2><p class="muted">${t('scopeHelp')}</p><div class="checklist">${cols.map(c=>`<label class="inline"><input type="checkbox" name="scope" value="${c.id}">${E(c.name)}</label>`).join('')||`<p class="muted">${t('noCollections')}</p>`}</div><label>${t('searchBtn')}<select id="search-mode"><option value="hybrid">${t('hybrid')}</option><option value="text">${t('text')}</option><option value="semantic">${t('semantic')}</option></select></label>${providerControls('search')}</div><div><div class="panel"><h2>${t('query')}</h2><div class="searchbox"><textarea id="search-query" placeholder="${t('query')}"></textarea><button class="primary" id="search-button">${t('searchBtn')} ↗</button></div><div class="row"><button id="ask-button">${t('ask')}</button><span class="muted">${t('sourceNotice')}</span></div></div><div id="search-output"></div><div class="spacer"></div><details><summary>${t('history')}</summary><div id="chat-history"></div></details></div></div>`;bindProvider('search');const query=()=>({query:$('#search-query').value,collections:$$('input[name=scope]:checked').map(x=>+x.value),mode:$('#search-mode').value,...providerValues('search')});const doSearch=chat=>async e=>busy(e.target,async()=>{if(!$('#search-query').value.trim())return;if(chat){if(!$('#search-provider').value||!$('#search-model').value)throw Error(et('Selecciona servidor y modelo antes de preguntar.','Select server and model before asking.'));await managedSelection($('#search-provider').value,$('#search-model').value);}$('#search-output').innerHTML=`<p class="muted busy">${t('loading')}</p>`;try{const r=await api(chat?'/chat':'/search',{method:'POST',body:query()});$('#search-output').innerHTML=(r.answer?`<div class="answer">${E(r.answer)}</div>`:'')+renderSources(r.sources||r.results||[]);bindSources();if(chat)loadHistory()}catch(err){$('#search-output').innerHTML='';throw err}});bind('#search-button','click',doSearch(false));bind('#ask-button','click',doSearch(true));await loadHistory()}
function renderSources(results){return `<div class="section-bar"><h2>${t('sources')} <span class="muted">/ ${results.length}</span></h2></div>`+(results.map((r,i)=>`<article class="source"><div class="source-title"><span class="badge">${i+1}</span><span>${E(r.path)}</span><span class="grow"></span><button class="small" data-source="${r.file_id}">${t('open')} ↗</button></div><div class="source-location">${E(r.collection_name)} · ${E(r.locator)}</div><div class="snippet">${E(r.text)}</div></article>`).join('')||`<div class="empty"><p>${t('noResults')}</p></div>`)}
function bindSources(){$$('[data-source]').forEach(b=>b.onclick=()=>preview(+b.dataset.source))}
async function loadHistory(){const el=$('#chat-history');if(!el)return;const h=await api('/conversations');el.innerHTML=h.map(r=>`<article class="source"><h3>${E(r.question)}</h3><p class="muted">${date(r.created)}</p><div class="snippet">${E(r.response)}</div></article>`).join('')}
let dataInfo=null;
async function renderAnalysis(){title('REPRODUCIBLE RESEARCH',t('analysisTitle'),t('analysisSub'),`<button id="new-analysis">＋ ${t('newAnalysis')}</button>`);$('#content').innerHTML=`<div class="notice">${t('analysisNote')}</div><div class="split"><div class="panel stack"><h2>${t('dataset')}</h2><label>${t('collections')}<select id="data-collection"><option value="">—</option>${cols.map(c=>`<option value="${c.id}">${E(c.name)}</option>`).join('')}</select></label><label>${t('file')}<select id="data-file"><option value="">—</option></select></label><label>${t('sheet')}<select id="data-sheet"><option value="">—</option></select></label><div id="data-summary" class="muted">${t('chooseDataset')}</div><label>${t('method')}<select id="analysis-method">${['describe','correlation','regression','ttest','wilcox','anova','chisq'].map(k=>`<option value="${k}">${t(k)}</option>`).join('')}</select></label><label>${t('columns')}</label><div id="data-columns" class="checklist"></div><label>${t('outcome')}<select id="data-outcome"></select></label><label>${t('group')}<select id="data-group"></select></label><button id="manual-plan">${t('manual')}</button></div><div class="stack"><div class="panel stack"><label>${t('question')}<textarea id="analysis-question" placeholder="${t('questionHint')}"></textarea></label>${providerControls('analysis')}<button class="primary" id="ai-plan">${t('aiPlan')}</button></div><div id="analysis-output"></div><details><summary>${t('history')}</summary><div id="analysis-history"></div></details></div></div>`;bindProvider('analysis');bind('#new-analysis','click',()=>renderAnalysis());bind('#data-collection','change',async()=>{dataInfo=null;$('#data-file').innerHTML='<option value="">—</option>';$('#data-sheet').innerHTML='';$('#data-columns').innerHTML='';$('#data-outcome').innerHTML='';$('#data-group').innerHTML='';if(!$('#data-collection').value)return;let files=await api(`/collections/${$('#data-collection').value}/files`);$('#data-file').innerHTML='<option value="">—</option>'+files.filter(f=>/\.(csv|tsv|xlsx)$/i.test(f.path)).map(f=>`<option value="${f.id}">${E(f.path)}</option>`).join('')});bind('#data-file','change',()=>loadSchema());bind('#data-sheet','change',()=>loadSchema($('#data-sheet').value));bind('#manual-plan','click',e=>preparePlan(e.target,false));bind('#ai-plan','click',e=>preparePlan(e.target,true));await loadAnalysisHistory()}
async function loadSchema(sheet){if(!$('#data-file').value)return;try{dataInfo=await api(`/files/${$('#data-file').value}/schema`+(sheet?'?sheet='+encodeURIComponent(sheet):''));$('#data-sheet').innerHTML=dataInfo.sheets.map(s=>`<option value="${E(s)}">${E(s)}</option>`).join('');$('#data-sheet').value=dataInfo.sheet;$('#data-summary').textContent=dataInfo.rows+' '+t('rows')+' · '+dataInfo.columns.length+' '+t('columns');$('#data-columns').innerHTML=dataInfo.columns.map(c=>`<label class="inline"><input type="checkbox" name="variable" value="${E(c.name)}">${E(c.name)} <span class="badge">${E(c.type)} · ${c.missing} ${t('missing')}</span></label>`).join('');const options=`<option value="">${t('none')}</option>`+dataInfo.columns.map(c=>`<option value="${E(c.name)}">${E(c.name)}</option>`).join('');$('#data-outcome').innerHTML=options;$('#data-group').innerHTML=options}catch(e){toast(e.message,true)}}
async function preparePlan(button,ai){await busy(button,async()=>{if(!$('#data-file').value)throw Error(t('chooseDataset'));const b={file_id:+$('#data-file').value,sheet:$('#data-sheet').value,question:$('#analysis-question').value,...providerValues('analysis')};if(!ai)b.plan={method:$('#analysis-method').value,columns:$$('input[name=variable]:checked').map(x=>x.value),outcome:$('#data-outcome').value,group:$('#data-group').value,explanation:''};let r=await api('/analyses/prepare',{method:'POST',body:b});currentAnalysis=r.id;showAnalysis(r);await loadAnalysisHistory()})}
function showAnalysis(r){const id=r.id;currentAnalysis=id;$('#analysis-output').innerHTML=`<div class="panel"><div class="section-bar"><h2>${t('code')}</h2><span class="badge">${t('prepared')}</span></div><p class="muted">${E(r.plan?.explanation||'')}</p><pre>${E(r.code)}</pre><p class="muted">${t('analysisReview')}</p><button id="run-analysis" class="primary">${t('run')} ↗</button><div id="r-output"></div></div>`;bind('#run-analysis','click',e=>busy(e.target,async()=>{let result=await api(`/analyses/${id}/run`,{method:'POST'});showResult(id,result);await loadAnalysisHistory()}));if(r.result)showResult(id,r)}
function showResult(id,r){$('#r-output').innerHTML=`<div class="section-bar"><h2>${t('results')}</h2><span class="badge ${r.state==='complete'?'good':''}">${t(r.state)}</span></div><pre>${E(r.result)}</pre>${r.figure||r.state==='complete'?`<img class="figure" src="/api/analyses/${id}/artifact/figure.svg" alt="R statistical plot">`:''}<div class="row"><a href="/api/analyses/${id}/artifact/analysis.zip" download>${t('export')} ↓</a>${r.state==='complete'?`<button id="interpret-analysis">${t('interpret')}</button>`:''}</div><div id="interpret-output"></div>`;const img=$('#r-output img');if(img)img.onerror=()=>img.remove();bind('#interpret-analysis','click',e=>busy(e.target,async()=>{let result=await api(`/analyses/${id}/interpret`,{method:'POST',body:providerValues('analysis')});$('#interpret-output').innerHTML=`<div class="answer">${E(result.answer)}</div>`}))}
async function loadAnalysisHistory(){const el=$('#analysis-history');if(!el)return;const results=await api('/analyses');el.innerHTML=results.map(r=>`<div class="source"><div class="row"><span class="grow">${E(r.question||t(JSON.parse(r.plan).method))}</span><span class="badge">${t(r.state)}</span><button class="small" data-analysis="${r.id}">${t('open')}</button></div><p class="muted">${date(r.created)}</p></div>`).join('')||`<p class="muted">${t('noAnalyses')}</p>`;$$('[data-analysis]').forEach(b=>b.onclick=async()=>{const r=await api('/analyses/'+b.dataset.analysis);r.plan=JSON.parse(r.plan);showAnalysis(r)})}
async function renderProviders(){
 title('LOCAL + CONNECTED',t('providerTitle'),t('providerSub'));
 $('#content').innerHTML=`<div id="engine-manager"></div><div class="notice">${et('Conexiones y perfiles de los proveedores. Los motores externos se conservan hasta una parada explícita.','Provider connections and profiles. External engines remain running until an explicit stop.')}</div><div class="cards">${Object.entries(providers).map(([name,c])=>`<form class="card stack" data-provider-form="${name}"><div class="row"><h2 class="grow">${providerName(name)}</h2><span class="badge ${c.credential?'good':''}">${t(c.credential?'connected':'noCredential')}</span></div><label>${t('url')}<input name="url" value="${E(c.url)}" ${me.role!=='admin'?'readonly':''}></label><label>${t('model')}<select name="model">${modelOptions(name,c.model)}</select></label><div class="muted" data-metadata></div><fieldset class="stack"><legend>${t('modelParameters')}</legend>${name==='openai'?`<label>${t('reasoning')}<select name="reasoning_effort"></select></label>`:`<div class="grid2"><label>${t('temperature')}<input name="temperature" type="number" min="0" max="2" step="0.05"></label><label>${t('topP')}<input name="top_p" type="number" min="0.01" max="1" step="0.01"></label></div><label>${t('maxTokens')}<input name="max_tokens" type="number" min="1" max="131072" step="1"></label><label>${t('contextLimit')}<input name="context_length" type="number" min="0" max="2000000" step="1"></label><p class="muted">${t('contextHelp')}</p>`}</fieldset><p class="muted" data-pending hidden>${t('profilePending')}</p><label>${t('key')}<input name="key" type="password" autocomplete="off" placeholder="${t('keyHint')}"></label>${name==='openai'?`<p class="muted">${t('oauthNote')}</p><button type="button" id="oauth-connect">${t('oauth')}</button><button type="button" id="oauth-disconnect" class="text-button">${t('disconnect')}</button><label class="inline"><input type="checkbox" name="consent">${t('consent')}</label>`:''}<div class="row"><button class="primary">${t('save')}</button><button type="button" data-activate="${name}">${et('Arrancar / cargar modelo','Start / load model')}</button><button type="button" data-models="${name}">${t('refreshModels')}</button><button type="button" data-test="${name}">${t('testInference')}</button></div><div id="provider-result-${name}" class="muted" role="status"></div></form>`).join('')}</div><p class="muted">${t('secretNote')}</p>`;
 $$('[data-provider-form]').forEach(form=>{
  const name=form.dataset.providerForm, el=form.elements, drafts={};let previous=el.model.value;
  const parameters=()=>name==='openai'?{reasoning_effort:el.reasoning_effort.value}:Object.fromEntries(['temperature','top_p','max_tokens','context_length'].map(k=>[k,Number(el[k].value)]));
  const detail=()=>{const id=el.model.value,p={...profileDefaults,...providers[name].profiles?.[id],...drafts[id]};form.querySelector('[data-metadata]').textContent=modelDescription(name,id);if(name==='openai')el.reasoning_effort.innerHTML=reasoningOptions(name,id,p.reasoning_effort);else for(const k of ['temperature','top_p','max_tokens','context_length'])el[k].value=p[k];form.querySelector('[data-pending]').hidden=!drafts[id];previous=id};
  const fill=()=>{const current=el.model.value||providers[name].model||'';el.model.innerHTML=modelOptions(name,current);el.model.value=current;detail()};
  el.model.onchange=e=>busy(e.target,async()=>{if(previous)drafts[previous]=parameters();const selected=el.model.value;await managedSelection(name,selected,Number(el.context_length?.value)||4096);detail()});
  form.querySelector('fieldset').oninput=()=>{form.querySelector('[data-pending]').hidden=false};
  form.onsubmit=e=>{e.preventDefault();busy(form.querySelector('.primary'),async()=>{if(me.role==='admin'){await api('/providers',{method:'POST',body:{name,url:el.url.value,model:el.model.value,key:el.key.value,parameters:el.model.value?parameters():null}})}else if(el.key.value){await api('/credentials',{method:'POST',body:{name,key:el.key.value}})}el.key.value='';delete drafts[el.model.value];if(name!=='openai'&&el.model.value)await managedSelection(name,el.model.value,Number(el.context_length.value)||4096);await refreshData();form.querySelector('[data-pending]').hidden=true;toast(t('saved'))})};
  form.querySelector('[data-activate]').onclick=e=>busy(e.target,async()=>{await managedSelection(name,el.model.value,Number(el.context_length?.value)||4096);await fetchCatalog(name,el.consent?.checked||false);fill()});
  const test=inference=>async e=>busy(e.target,async()=>{if(inference)await managedSelection(name,el.model.value,Number(el.context_length?.value)||4096);if(el.url.value.replace(/\/$/,'')!==providers[name].url||el.key.value)throw Error(t('saveEndpoint'));const result=await api('/providers/test',{method:'POST',body:{name,inference,model:el.model.value,parameters:inference?parameters():null,consent:el.consent?.checked||false,reasoning_effort:name==='openai'?el.reasoning_effort.value:null}});if(el.model.value&&!form.querySelector('[data-pending]').hidden)drafts[el.model.value]=parameters();modelCatalogs[catalogKey(name)]=result.catalog;fill();$(`#provider-result-${name}`).textContent=(result.answer?result.answer+' · ':'')+result.models.length+' '+t('model')});
  form.querySelector('[data-models]').onclick=e=>busy(e.target,async()=>{const s=await managedInfo();if(name!=='openai'&&s?.config.enabled){if(!s.running||s.active.name!==name)await managedSelection(name);await managedCatalog(name);fill()}else await test(false)(e)});form.querySelector('[data-test]').onclick=test(true);detail();
  if(name!=='openai')fetchCatalog(name).then(fill).catch(e=>{$(`#provider-result-${name}`).textContent=e.message});
 });
 bind('#oauth-connect','click',e=>busy(e.target,async()=>{const r=await api('/oauth/start',{method:'POST'});if(window.webkit?.messageHandlers?.openExternal)window.webkit.messageHandlers.openExternal.postMessage({url:r.url});else window.open(r.url,'_blank','noopener');toast(t('oauthStarted'))}));
 bind('#oauth-disconnect','click',e=>busy(e.target,async()=>{await api('/oauth/disconnect',{method:'POST'});delete modelCatalogs[catalogKey('openai')];await navigate('providers')}));await renderEngineManager();
}

async function renderUsers(){if(me.role!=='admin')return;title('ACCESS & PERMISSIONS',t('usersTitle'),t('usersSub'),`<button class="primary" id="new-user">＋ ${t('newUser')}</button>`);let us=await api('/users');$('#content').innerHTML=`<div class="notice">${t('userNote')}</div><div class="data-table-wrap"><table><thead><tr><th>${t('username')}</th><th>${t('role')}</th><th>${t('status')}</th><th></th></tr></thead><tbody>${us.map(u=>`<tr><td>${E(u.username)}</td><td>${t(u.role)}</td><td>${t(u.active?'active':'inactive')}</td><td>${u.id!==me.id?`<button class="small" data-toggle-user="${u.id}">${t(u.active?'disable':'enable')}</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="spacer"></div><div class="panel"><h2>${t('grant')}</h2><form class="stack" id="grant-form"><div class="grid2"><label>${t('username')}<select id="grant-user">${us.filter(u=>u.role!=='admin').map(u=>`<option value="${u.id}">${E(u.username)}</option>`).join('')}</select></label><label>${t('collections')}<select id="grant-col">${cols.map(c=>`<option value="${c.id}">${E(c.name)}</option>`).join('')}</select></label></div><label>${t('permission')}<select id="grant-permission"><option value="read">${t('read')}</option><option value="edit">${t('write')}</option><option value="none">${t('revoke')}</option></select></label><button class="primary">${t('save')}</button></form><div id="grants-output"></div></div>`;bind('#new-user','click',()=>{modal(`<h2>${t('newUser')}</h2><form id="new-user-form" class="stack"><label>${t('username')}<input id="new-username" required minlength="2"></label><label>${t('password')}<input id="new-password" required type="password" minlength="10" placeholder="${t('minPassword')}"></label><label>${t('role')}<select id="new-role">${['reader','editor','admin'].map(r=>`<option value="${r}">${t(r)}</option>`).join('')}</select></label><button class="primary">${t('save')}</button></form>`);bind('#new-user-form','submit',e=>{e.preventDefault();busy($('#new-user-form button'),async()=>{await api('/users',{method:'POST',body:{username:$('#new-username').value,password:$('#new-password').value,role:$('#new-role').value}});close();await renderUsers()})})});$$('[data-toggle-user]').forEach(b=>b.onclick=()=>busy(b,async()=>{const u=us.find(u=>u.id===+b.dataset.toggleUser);await api('/users/'+u.id,{method:'PATCH',body:{active:!u.active,role:u.role}});await renderUsers()}));bind('#grant-form','submit',e=>{e.preventDefault();busy($('#grant-form button'),async()=>{if(!$('#grant-col').value||!$('#grant-user').value)return;await api(`/collections/${$('#grant-col').value}/grants`,{method:'POST',body:{user_id:+$('#grant-user').value,permission:$('#grant-permission').value}});toast(t('saved'));await showGrants()})});bind('#grant-col','change',showGrants);await showGrants()}
async function showGrants(){if(!$('#grant-col')?.value)return;const grants=await api(`/collections/${$('#grant-col').value}/grants`);$('#grants-output').innerHTML='<div class="spacer"></div>'+grants.map(g=>`<p class="muted">${E(g.username)} · ${t(g.permission==='edit'?'write':'read')}</p>`).join('')}
async function renderActivity(){title('SERVER OBSERVATORY',t('activityTitle'),t('activitySub'),`<button id="refresh">↻ ${t('refresh')}</button>`);const jobs=await api('/jobs');$('#content').innerHTML=metrics()+`<div class="grid2"><div class="panel"><h2>${t('systemMemory')}</h2><p>${bytes(stats.memory.available)} / ${bytes(stats.memory.total)}</p><div class="progress"><div style="width:${stats.memory.percent}%"></div></div><p class="muted">CPU RAG: ${stats.cpu.toFixed(1)}% · ${t('swap')}: ${bytes(stats.memory.swap)} · ${stats.r?t('rReady'):'R unavailable'}</p></div>${stats.storage?`<div class="panel"><h2>${t('storage')}</h2>${Object.entries(stats.storage).map(([k,v])=>`<div class="row"><span class="muted grow">${t({index:'indexDisk',analyses:'analysesDisk',backups:'backups',trash:'trashDisk',logs:'logs'}[k])}</span><span>${bytes(v)}</span></div>`).join('')}</div>`:''}</div><div class="section-bar"><h2>${t('jobs')}</h2></div><div>${jobs.map(j=>`<article class="source"><div class="row"><span class="grow">${E(cols.find(c=>c.id===j.collection_id)?.name||'')}</span><span class="badge ${j.state==='complete'?'good':''}">${t(j.state)}</span>${['running','queued'].includes(j.state)?`<button class="small" data-cancel="${j.id}">${t('cancel')}</button>`:''}</div><div class="progress"><div style="width:${j.total?j.done/j.total*100:0}%"></div></div><span class="muted">${j.done}/${j.total} · ${E(j.message)} · ${j.errors} ${t('error')}</span></article>`).join('')||`<p class="muted">${t('noJobs')}</p>`}</div><div id="audit-output"></div>`;bind('#refresh','click',()=>navigate('activity'));$$('[data-cancel]').forEach(b=>b.onclick=()=>busy(b,async()=>{await api(`/jobs/${b.dataset.cancel}/cancel`,{method:'POST'});await renderActivity()}));if(me.role==='admin'){const [audits,logs]=await Promise.all([api('/audit'),api('/logs')]);$('#audit-output').innerHTML=`<div class="section-bar"><h2>${t('audit')}</h2></div><div class="data-table-wrap"><table><thead><tr><th>${t('date')}</th><th>${t('username')}</th><th>${t('action')}</th><th>${t('target')}</th></tr></thead><tbody>${audits.map(a=>`<tr><td>${date(a.created)}</td><td>${E(a.username)}</td><td>${E(a.action)}</td><td>${E(a.target)}</td></tr>`).join('')}</tbody></table></div><details><summary>${t('logs')}</summary><pre>${E(logs.text)}</pre></details>`}}
(async()=>{try{const h=await api('/health');if(h.setup){await authenticate(true);return}try{me=await api('/me')}catch{await authenticate(false);return}$('#auth').hidden=true;$('#shell').hidden=false;translateShell();await navigate('collections')}catch(e){$('#auth').hidden=false;$('#auth').textContent=e.message}})();
setInterval(async()=>{if(!me||$('#modal').open)return;try{stats=await api('/stats');$('#footer-status').textContent=bytes(stats.rss)+' RAM · '+bytes(stats.disk.free)+' '+t('freeDisk')+' · '+(stats.disk.volume||'');if(page==='providers'&&me.role==='admin'&&$('#engine-status')){const engine=await managedInfo();$('#engine-status').textContent=engine.job.busy?et('Cambiando motor o modelo…','Switching engine or model…'):engineSummary(engine);if($('#lmstudio-state'))$('#lmstudio-state').textContent=lmstudioSummary(engine)}if(page==='collections'){if(!activeCollection&&$('.metrics'))$('.metrics').outerHTML=metrics();const latest=await api('/collections');if(JSON.stringify(latest)!==JSON.stringify(cols)){cols=latest;if(activeCollection)await openCollection(activeCollection);else await renderCollections()}}}catch{}},6000);
